import{z as n,x as s,o as l,c as R,q as e,j as t,D as a,d as r,s as o,S as i,b as B}from"./chunks/framework.C8m1ZpeB.js";const f=JSON.parse('{"title":"回到后训练：RLHF/GRPO/RLVR 的位置","description":"","frontmatter":{"title":"回到后训练：RLHF/GRPO/RLVR 的位置","date":"2026-09-18T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/rl-foundations-map.md","filePath":"llm/rl-foundations-map.md","lastUpdated":1791413859000}'),m={name:"llm/rl-foundations-map.md"};function F(p,E,d,D,h,C){const A=s("Mermaid");return l(),R("div",null,[E[2]||(E[2]=e('<h1 id="回到后训练-rlhf-grpo-rlvr-的位置" tabindex="-1">回到后训练：RLHF/GRPO/RLVR 的位置 <a class="header-anchor" href="#回到后训练-rlhf-grpo-rlvr-的位置" aria-label="Permalink to &quot;回到后训练：RLHF/GRPO/RLVR 的位置&quot;">​</a></h1><div class="epigraph"><p>理论保证是一本账：每条后训练路线都从账上划掉一项，换来一个跑得动的算法。</p><footer>—— 据 Schulman 等 2017、Shao 等 2024、Lambert 等 2024 的方法形态整理</footer></div><p><a href="/llm/reward-overoptimization-theory">上一课</a>给奖励过优化立了理论骨架：残差、压力、支撑距离三个可监控量。本课程从 <a href="/llm/mdp-five-tuple">MDP 五元组</a>出发，经无模型学习与信任域，到 bandit、离线与过优化，至此收束。本课做收束该做的事：把 RLHF/GRPO/RLVR/自博弈逐一放回本课程的概念坐标，写明每条路线留用什么、牺牲了哪个理论保证。<strong>后课默认已读完本课程</strong>；下一课程「奖励、自博弈与推理行为」从奖励模型进阶开卷（<a href="/llm/rm-ensembles">RM 集成与不确定性</a>），把被本课程当成真值的那个标量奖励拆开。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>课程是一部「保证的修复史」：<a href="/llm/policy-gradient-theorem">策略梯度定理</a>给无偏方向；REINFORCE 方差太大，<a href="/llm/baselines-advantage">基线与优势</a>不改期望只降方差；自举换方差（<a href="/llm/actor-critic-bootstrap">actor-critic 与自举</a>）引入致命三要素的一角；<a href="/llm/trust-region-monotone">信任域与单调改进</a>给出 KL 球内的单调改进，<a href="/llm/ppo-clip-view">PPO 的信任域重读</a>把它软化成可跑的 clip。缺口是这些零件在真实后训练里如何被取舍：每条知名路线各留哪个保证、扔哪个，扔掉之后用什么东西垫底。</p><p><span class="marginnote">把「理论保证」想成保险单：RLHF 保得全但保费贵（二阶优化、KL 球）；GRPO 退掉 critic 那份险，用同提示互相比较垫底；自博弈干脆换了一种险种。每退一份险，都要说清出事时谁兜底——本课就是这张保单对照表。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>四条映射，逐条过账。<strong><a href="/llm/rlhf-pipeline">RLHF 流程</a></strong>：离线偏好数据训 <a href="/llm/reward-model">奖励模型</a>，这是<a href="/llm/offline-rl-shift">离线 RL 与分布偏移</a>的支撑问题；PPO 或 GRPO 更新，用信任域与基线；KL 正则当压力旋钮，按<a href="/llm/reward-overoptimization-theory">奖励过优化的理论视角</a>定价。牺牲的保证：KL 球内的改进只是近似单调（clip 是软约束），且代理间隙被优化压力放大。<strong><a href="/llm/grpo">GRPO</a></strong>：REINFORCE（<a href="/llm/reinforce-variance">REINFORCE 与方差</a>）加组内基线——同提示一组奖励减均值，正是不改期望的 \\(b(x)\\)。牺牲：critic，逐 token 自举的那半方差减缩（GAE 一翼）没了，优势只到序列与组级。<strong><a href="/llm/rlvr">RLVR</a></strong>：验证器当奖励，稀疏常数标量。牺牲：覆盖面（只在可验证域），且验证器自己成为新代理，间隙换宿主；稀疏奖励又把方差推回蒙特卡洛端（<a href="/llm/monte-carlo-evaluation">蒙特卡洛策略评估</a>）。<strong><a href="/llm/self-play-lm">自博弈</a></strong>：对手取自旧版本策略，胜负当奖励，绕开 RM。牺牲：MDP 固定假设——环境随策略变，非平稳之下单调改进的前提（固定 \\(\\mathcal{M}\\)）不成立。</p><p><span class="marginnote">「不改期望只降方差」的直觉版：同一提示采 8 个回答，它们共同面临的「提示本身难」的成分在相减时抵消，剩下的才是「这个回答比同伴好多少」。减均值不改变好坏排序，只把衡量基准从绝对分换成组内相对分。</span></p><p><span class="marginnote">GRPO 的组基线只在同提示内可比时成立：\\(b(x)\\) 里的 \\(x\\) 必须是同一情境；把不同提示的奖励混进一个均值，基线就依赖动作，「不改期望」的证明失效。</span></p>',10)),(l(),t(i,null,{default:a(()=>[o(A,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20CORE%5B%22%E5%85%B1%E5%90%8C%E5%86%85%E6%A0%B8%EF%BC%9A%E5%B8%A6%E5%9F%BA%E7%BA%BF%E7%9A%84%E7%AD%96%E7%95%A5%E6%A2%AF%E5%BA%A6%20%2B%20%E8%BD%AF%E4%BF%A1%E4%BB%BB%E5%9F%9F%22%5D%20--%3E%20RLHF%5B%22RLHF%EF%BC%9A%E7%A6%BB%E7%BA%BF%E5%81%8F%E5%A5%BD%E8%AE%AD%20RM%20%2B%20KL%20%E6%97%8B%E9%92%AE%22%5D%0A%20%20CORE%20--%3E%20GRP%5B%22GRPO%EF%BC%9A%E7%BB%84%E5%86%85%E5%9F%BA%E7%BA%BF%EF%BC%8C%E5%BC%83%20critic%22%5D%0A%20%20CORE%20--%3E%20RLVR%5B%22RLVR%EF%BC%9A%E9%AA%8C%E8%AF%81%E5%99%A8%E5%A5%96%E5%8A%B1%EF%BC%8C%E5%BC%83%E8%A6%86%E7%9B%96%E9%9D%A2%22%5D%0A%20%20CORE%20--%3E%20SP%5B%22%E8%87%AA%E5%8D%9A%E5%BC%88%EF%BC%9A%E6%97%A7%E7%89%88%E6%9C%AC%E5%BD%93%E5%AF%B9%E6%89%8B%EF%BC%8C%E5%BC%83%E5%9B%BA%E5%AE%9A%20MDP%22%5D%0A%20%20RLHF%20--%3E%20S1%5B%22%E4%BB%A3%E4%BB%B7%EF%BC%9A%E8%BF%91%E4%BC%BC%E5%8D%95%E8%B0%83%20%2B%20%E4%BB%A3%E7%90%86%E9%97%B4%E9%9A%99%22%5D%0A%20%20GRP%20--%3E%20S2%5B%22%E4%BB%A3%E4%BB%B7%EF%BC%9A%E6%97%A0%E9%80%90%20token%20%E8%87%AA%E4%B8%BE%22%5D%0A%20%20RLVR%20--%3E%20S3%5B%22%E4%BB%A3%E4%BB%B7%EF%BC%9A%E6%96%B0%E4%BB%A3%E7%90%86%20%2B%20%E9%AB%98%E6%96%B9%E5%B7%AE%22%5D%0A%20%20SP%20--%3E%20S4%5B%22%E4%BB%A3%E4%BB%B7%EF%BC%9A%E9%9D%9E%E5%B9%B3%E7%A8%B3%EF%BC%8C%E6%97%A0%E6%94%B6%E6%95%9B%E4%BF%9D%E8%AF%81%22%5D%0A"})]),fallback:a(()=>[...E[0]||(E[0]=[r(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=B("h2",{id:"机制",tabindex:"-1"},[r("机制 "),B("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),E[4]||(E[4]=B("p",null,"把四条路线放进一个坐标系，账目就清楚。不变的核心只有一件：带基线的策略梯度，配一个软化的信任域——没有任何主流路线放弃这两个。可替换的坐标有三个：奖励来源（人类偏好、RM、验证器、胜负），基线形态（critic、组统计、无），数据分布（同策略 rollout、离线比较对、自产自消）。「某条路线牺牲了哪个保证」就翻译成「它在三个坐标上选了哪个点」：换奖励来源是重新分配代理间隙（RLHF 承担 RM 的，RLVR 承担验证器的，自博弈希望胜负无间隙但要求可检验）；换基线是重排偏差方差（critic 拿自举的偏差换方差，GRPO 拒绝这笔交易）；换数据分布是重付离线与在线的价（RLHF 的偏好数据带支撑问题，同策略 rollout 付算力）。",-1)),E[5]||(E[5]=B("p",null,"选型时「在三个坐标上选点」意味着什么：",-1)),(l(),t(i,null,{default:a(()=>[o(A,{id:"mermaid-38",class:"mermaid",graph:"flowchart%20TD%0A%20%20Q%5B%22%E9%80%89%E8%B7%AF%E7%BA%BF%20%3D%20%E5%9C%A8%E4%B8%89%E4%B8%AA%E5%9D%90%E6%A0%87%E4%B8%8A%E5%90%84%E9%80%89%E4%B8%80%E7%82%B9%22%5D%20--%3E%20C1%5B%22%E5%9D%90%E6%A0%87%E4%B8%80%EF%BC%9A%E5%A5%96%E5%8A%B1%E6%9D%A5%E6%BA%90%22%5D%0A%20%20Q%20--%3E%20C2%5B%22%E5%9D%90%E6%A0%87%E4%BA%8C%EF%BC%9A%E5%9F%BA%E7%BA%BF%E5%BD%A2%E6%80%81%22%5D%0A%20%20Q%20--%3E%20C3%5B%22%E5%9D%90%E6%A0%87%E4%B8%89%EF%BC%9A%E6%95%B0%E6%8D%AE%E5%88%86%E5%B8%83%22%5D%0A%20%20C1%20--%3E%20O1%5B%22%E4%BA%BA%E7%B1%BB%E5%81%8F%E5%A5%BD%20%2F%20RM%20%2F%20%E9%AA%8C%E8%AF%81%E5%99%A8%20%2F%20%E8%83%9C%E8%B4%9F%22%5D%0A%20%20O1%20--%3E%20P1%5B%22%E6%8D%A2%E5%A5%96%E5%8A%B1%20%3D%20%E9%87%8D%E6%96%B0%E5%88%86%E9%85%8D%E4%BB%A3%E7%90%86%E9%97%B4%E9%9A%99%22%5D%0A%20%20C2%20--%3E%20O2%5B%22critic%20%2F%20%E7%BB%84%E7%BB%9F%E8%AE%A1%20%2F%20%E6%97%A0%22%5D%0A%20%20O2%20--%3E%20P2%5B%22%E6%8D%A2%E5%9F%BA%E7%BA%BF%20%3D%20%E9%87%8D%E6%8E%92%E5%81%8F%E5%B7%AE%E4%B8%8E%E6%96%B9%E5%B7%AE%22%5D%0A%20%20C3%20--%3E%20O3%5B%22%E5%90%8C%E7%AD%96%E7%95%A5%20rollout%20%2F%20%E7%A6%BB%E7%BA%BF%E5%AF%B9%20%2F%20%E8%87%AA%E4%BA%A7%E8%87%AA%E6%B6%88%22%5D%0A%20%20O3%20--%3E%20P3%5B%22%E6%8D%A2%E5%88%86%E5%B8%83%20%3D%20%E9%87%8D%E4%BB%98%E5%9C%A8%E7%BA%BF%E7%AE%97%E5%8A%9B%E6%88%96%E7%A6%BB%E7%BA%BF%E6%94%AF%E6%92%91%E7%9A%84%E4%BB%B7%22%5D%0A"})]),fallback:a(()=>[...E[1]||(E[1]=[r(" Loading... ",-1)])]),_:1})),E[6]||(E[6]=e('<p><a href="/llm/contextual-bandits">上下文 bandit</a> 在坐标系里也有位置：单轮偏好与序列级奖励把生成当一拍动作，是有意选了 bandit 近似、把方差当账单。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>地图的失效方式。GRPO 不是 REINFORCE 原教旨：裁剪与 KL 正则通常都在，软信任域没有丢。RLVR 的奖励可以被过程奖励稠密化，不是天然稀疏。自博弈在语言里常退化成对旧版本的偏好优化，靠近离线一端，棋类的纯净胜负并不多得。所以这张图是记忆架与选型表，不是分类学：路线之间的迁移（给 GRPO 加过程奖励、给 RLVR 换基线）在坐标系上就是移动一个点。</p><p><span class="marginnote">初学者容易把这张图读成「哪条路线最强」的排行榜；它是选型表。问法应该是：我有没有可验证的奖励？显存养不养得起 critic？数据能不能在线采？——三个答案不同，最优点就落在不同坐标上。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>共同内核：带基线的策略梯度加软信任域；RLHF/GRPO/RLVR/自博弈都在三个坐标（奖励来源、基线、数据分布）上选点。</li><li>RLHF 牺牲近似单调性与代理间隙的可控性；GRPO 牺牲 critic 与逐 token 自举；RLVR 牺牲覆盖面并把间隙交给验证器；自博弈牺牲平稳性与收敛保证。</li><li>bandit、离线、过优化三课是坐标系的三根轴：一拍近似、支撑约束、压力定价。</li><li>本课程收束：后课默认已读完本课程；下一课程从<a href="/llm/rm-ensembles">奖励模型进阶</a>开卷，拆解被当成真值的标量奖励。</li><li>出处：Schulman 等 2017（PPO）；Shao 等 2024（GRPO）；Lambert 等 2024（RLVR）；Silver 等（自博弈），据各方法原文形态整理。</li></ul>',6))])}const P=n(m,[["render",F]]);export{f as __pageData,P as default};
